1	{% extends "base.html" %}
2	{% block title %}Observations{% endblock %}
3	{% block content %}
4	<h1>Observations</h1>
5	<p><a href="{% url 'observation_create' %}">New observation</a> · <a href="{% url 'dashboard' %}">Dashboard</a></p>
6	{% if observations %}
7	<table>
8	  <thead><tr><th>Date</th><th>Pupil</th><th>Mood</th><th>Author</th></tr></thead>
9	  <tbody>
10	  {% for o in observations %}
11	    <tr>
12	      <td><a href="{% url 'observation_detail' o.pk %}">{{ o.observed_on }}</a></td>
13	      <td>{{ o.pupil }}</td>
14	      <td>{{ o.get_mood_display }}</td>
15	      <td>{{ o.author.get_full_name|default:o.author.username }}</td>
16	    </tr>
17	  {% endfor %}
18	  </tbody>
19	</table>
20	{% else %}
21	<p>No observations yet. Record the first one with the link above.</p>
22	{% endif %}
23	{% endblock %}
