1	{% extends "base.html" %}
2	{% block title %}Dashboard{% endblock %}
3	{% block content %}
4	<h1>Dashboard</h1>
5	<p>{{ total_pupils }} pupils, observations since {{ since }}.</p>
6	{% if alerts %}
7	<p><strong>Needs attention:</strong> {% for p in alerts %}{{ p }}{% if not forloop.last %}, {% endif %}{% endfor %}</p>
8	{% endif %}
9	<table>
10	  <thead><tr><th>Pupil</th><th>Total</th><th>Anxious</th><th>Withdrawn</th><th>Dysregulated</th><th>Concern</th><th>Level</th><th>Latest</th></tr></thead>
11	  <tbody>
12	  {% for r in rows %}
13	    <tr>
14	      <td>{{ r.pupil }}</td><td>{{ r.total }}</td><td>{{ r.anxious }}</td><td>{{ r.withdrawn }}</td>
15	      <td>{{ r.dysregulated }}</td><td>{{ r.concern }}%</td><td>{{ r.level }}</td>
16	      <td>{% if r.latest %}{{ r.latest.observed_on }} ({{ r.latest_author }}){% endif %}</td>
17	    </tr>
18	  {% endfor %}
19	  </tbody>
20	</table>
21	{% endblock %}
